public static int findLargestSubstring(List<String> strings) {
        int maxLen = 0;

        for (String str : strings) {
            for (int i = 0; i < str.length(); i++) {
                String forward = str.substring(i);
                String backward = new StringBuilder(str.substring(i)).reverse().toString();

                if (strings.stream().anyMatch(s -> s.contains(forward) || s.contains(backward))) {
                    maxLen = Math.max(maxLen, forward.length());
                }
            }
        }

        return maxLen;
    }

public int findLargestSubstring(List<String> strings) {
    Set<String> substrings = new HashSet<>();
    Set<String> inverseSubstrings = new HashSet<>();

    for (String str : strings) {
        for (int i = 0; i <= str.length(); i++) {
            for (int j = i; j <= str.length(); j++) {
                String substring = str.substring(i, j);
                substrings.add(substring);
                inverseSubstrings.add(new StringBuilder(substring).reverse().toString());
            }
        }
    }

    int maxLength = 0;

    for (String substring : substrings) {
        if (inverseSubstrings.contains(substring)) {
            maxLength = Math.max(maxLength, substring.length());
        }
    }

    return maxLength;
}

