public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] grid = new boolean[n][n];
    for (int[] path : paths) {
        grid[path[0]][path[1]] = true;
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    boolean[][] visited = new boolean[n][n];
    boolean[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    Queue<int[]> queue = new ArrayDeque<>();
    queue.add(new int[]{startX, startY});
    visited[startX][startY] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == endX && y == endY) {
            return "can be travelled";
        }

        for (int[] direction : directions) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            if (newX >= 0 && newX < n && newY >= 0 && newY < n && grid[newX][newY] && !visited[newX][newY]) {
                queue.add(new int[]{newX, newY});
                visited[newX][newY] = true;
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] graph = new boolean[n][n];
    boolean[] visited = new boolean[n];

    // Build the graph based on the given paths
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        graph[from][to] = true;
        graph[to][from] = true;
    }

    // Helper function to perform DFS
    boolean dfs(int current, int destination) {
        if (current == destination) {
            return true;
        }
        visited[current] = true;
        for (int i = 0; i < n; i++) {
            if (graph[current][i] && !visited[i]) {
                if (dfs(i, destination)) {
                    return true;
                }
            }
        }
        visited[current] = false;
        return false;
    }

    // Check if there is a path from start to end
    if (dfs(start[0], end[0])) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

