public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    Set<Integer> visited = new HashSet<>();
    boolean[] pathExists = new boolean[paths.length];
    for (int i = 0; i < paths.length; i++) {
        pathExists[i] = false;
    }
    int startVertex = start[0] * n + start[1];
    int endVertex = end[0] * n + end[1];
    boolean canReachEnd = dfs(startVertex, endVertex, visited, pathExists, paths);
    if (canReachEnd) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(int current, int end, Set<Integer> visited, boolean[] pathExists, int[][] paths) {
    visited.add(current);
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        if (from == current && !visited.contains(to) && !pathExists[pathExists.length - 1]) {
            pathExists[pathExists.length - 1] = true;
            if (to == end) {
                return true;
            }
            if (dfs(to, end, visited, pathExists, paths)) {
                return true;
            }
            pathExists[pathExists.length - 1] = false;
        }
    }
    visited.remove(current);
    return false;
}

