        }

        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int[] path : paths) {
            int from = path[0];
            int to = path[1];
            graph.computeIfAbsent(from, k -> new ArrayList<>()).add(to);
            graph.computeIfAbsent(to, k -> new ArrayList<>()).add(from);
        }

        Queue<Integer> queue = new LinkedList<>();
        Set<Integer> visited = new HashSet<>();
        queue.offer(start[0] * n + start[1]);
        visited.add(start[0] * n + start[1]);

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int[] currentCoords = getCoordinates(current, n);
            if (currentCoords[0] == end[0] && currentCoords[1] == end[1]) {
                return "can be travelled";
            }

            for (int neighbor : getNeighbors(current, n)) {
                if (!visited.contains(neighbor)) {
                    queue.offer(neighbor);
                    visited.add(neighbor);
                }
            }
        }

        return "cannot be travelled";
    }

private static int[] getCoordinates(int linearIndex, int n) {
        return new int[] { linearIndex / n, linearIndex % n };
    }

private static Set<Integer> getNeighbors(int linearIndex, int n) {
        int[] coords = getCoordinates(linearIndex, n);
        Set<Integer> neighbors = new HashSet<>();
        if (coords[0] > 0) neighbors.add((coords[0] - 1) * n + coords[1]);
        if (coords[0] < n - 1) neighbors.add((coords[0] + 1) * n + coords[1]);
        if (coords[1] > 0) neighbors.add(coords[0] * n + coords[1] - 1);
        if (coords[1] < n - 1) neighbors.add(coords[0] * n + coords[1] + 1);
        return neighbors;
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    List<int[]>[][] graph = new List[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            graph[i][j] = new ArrayList<>();
        }
    }
    for (int[] path : paths) {
        graph[path[0]][path[1]].add(path);
        graph[path[1]][path[0]].add(path);
    }
    boolean[] visited = new boolean[n];
    if (dfs(graph, start[0], start[1], end[0], end[1], visited)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean dfs(List<int[]>[][] graph, int x, int y, int endX, int endY, boolean[] visited) {
    if (x == endX && y == endY) {
        return true;
    }
    visited[x] = true;
    for (int[] path : graph[x][y]) {
        if (!visited[path[0]]) {
            if (dfs(graph, path[0], path[1], endX, endY, visited)) {
                return true;
            }
        }
    }
    visited[x] = false;
    return false;
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) != -1) {
            commonLetters++;
        }
    }
    int sumOfLengths = word1.length() + word2.length();
    return "appx(" + word1 + ", " + word2 + ") = " + (commonLetters) + "/" + sumOfLengths;
}

public static String appx(String word1, String word2) {
        int commonLetters = 0;
        int lengthSum = word1.length() + word2.length();

        for (char c : word1.toLowerCase().toCharArray()) {
            if (word2.toLowerCase().indexOf(c) != -1) {
                commonLetters++;
            }
        }

        BigInteger numerator = BigInteger.valueOf(commonLetters);
        BigInteger denominator = BigInteger.valueOf(lengthSum);
        BigInteger gcd = numerator.gcd(denominator);

        numerator = numerator.divide(gcd);
        denominator = denominator.divide(gcd);

        return String.format("appx(%s, %s) = %s/%s", word1, word2, numerator, denominator);
    }

public static String appx(String word1, String word2) {
        Set<Character> commonLetters = new HashSet<>();
        for (char c : word1.toCharArray()) {
            if (word2.indexOf(c) != -1) {
                commonLetters.add(c);
            }
        }

        int numerator = commonLetters.size();
        int denominator = word1.length() + word2.length() - numerator;

        int gcd = gcd(numerator, denominator);
        numerator /= gcd;
        denominator /= gcd;

        return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
    }

private static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

public static String appx(String word1, String word2) {
