        for (char c : word1.toCharArray()) {
            set1.add(c);
        }

        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        int commonCount = 0;
        for (char c : set1) {
            if (set2.contains(c)) {
                commonCount++;
            }
        }

        int lengthSum = word1.length() + word2.length();

        return "appx(" + word1 + ", " + word2 + ") = " + (commonCount * 1.0 / lengthSum);
    }

