public boolean canArrange(int[] arr, int k) {
    int[] remainderCounts = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        remainderCounts[remainder]++;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false;
        }
    }

    return remainderCounts[0] % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
    int[] remainder_counts = new int[k];
    for (int num : arr) {
        int remainder = (num % k + k) % k; // Ensure positive remainder
        remainder_counts[remainder]++;
    }
    if (remainder_counts[0] % 2 != 0) {
        return false; // Zero remainder must have an even count
    }
    for (int i = 1; i <= k / 2; i++) {
        if (remainder_counts[i] != remainder_counts[k - i]) {
            return false; // Remainders must mirror around k/2
        }
    }
    return true;
}

