public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> adjList = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            adjList.get(edge[0]).add(edge[1]);
            adjList.get(edge[1]).add(edge[0]);
        }

        return dfs(0, -1, adjList, hasApple) * 2;
    }

private int dfs(int node, int parent, List<List<Integer>> adjList, boolean[] hasApple) {
        int time = 0;
        for (int neighbor : adjList.get(node)) {
            if (neighbor == parent) continue;
            time += dfs(neighbor, node, adjList, hasApple);
        }
        if ((time > 0 || hasApple[node]) && node != 0) {
            time += 2;
        }
        return time;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create an adjacency list to represent the tree
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }

    // Helper method to perform depth-first search and return the time
    return helper(tree, -1, 0, hasApple);
}

private int helper(List<List<Integer>> tree, int parent, int node, boolean[] hasApple) {
    int time = 0;
    for (int child : tree.get(node)) {
        if (child != parent) {
            int childTime = helper(tree, node, child, hasApple);
            if (childTime > 0 || hasApple[child]) {
                time += childTime + 2; // Add 2 for the time to go to and return from the child node
            }
        }
    }
    return time;
}

