public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    boolean[] possibleAverages = new boolean[sum + 1];
    possibleAverages[0] = true;

    for (int num : nums) {
        for (int j = sum; j >= num; j--) {
            possibleAverages[j] = possibleAverages[j] || possibleAverages[j - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (possibleAverages[i * sum / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] A) {
    int n = A.length;
    int sum = 0;
    for (int num : A) {
        sum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (check(A, i, sum, 0, 0, n)) {
            return true;
        }
    }

    return false;
}

private boolean check(int[] A, int targetSize, int targetSum, int start, int currentSum, int n) {
    if (currentSize == targetSize) {
        return targetSum == currentSum;
    }

    for (int i = start; i < n; i++) {
        if (check(A, targetSize, targetSum, i + 1, currentSum + A[i], n)) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    Set<Integer>[] possibleAverages = new Set[n / 2 + 1];
    for (int i = 0; i <= n / 2; i++) {
        possibleAverages[i] = new HashSet<>();
    }

    possibleAverages[0].add(0);
    for (int num : nums) {
        for (int i = n / 2; i > 0; i--) {
            for (int avg : possibleAverages[i - 1]) {
                possibleAverages[i].add(avg + num);
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (possibleAverages[i].contains(sum * i / n)) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] A) {
    int n = A.length, sum = 0;
    for (int a : A) sum += a;
    for (int i = 0; i < A.length; ++i)
        A[i] = (A[i] * n - sum) << 10; // Scale by 2n to avoid floating point division
    Arrays.sort(A);
    boolean[][] dp = new boolean[n+1][sum+1];

    // Initialize base cases
    dp[0][0] = true;

    // Fill dp table
    for (int i = 1; i <= n; ++i) {
        for (int j = sum; j >= A[i-1]; --j) {
            dp[i][j] = dp[i-1][j] || dp[i-1][j-A[i-1]];
        }
    }

    // Check for possible splits
    for (int i = 1; i <= n / 2; ++i) {
        if (dp[i][0]) continue;
        int target = (sum * i) / n;
        if (target * 2 >= sum) break; // Early exit if target is out of range
        if (dp[i][target]) return true;
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int totalSum = 0;
    for (int num : nums) totalSum += num;

    for (int i = 0; i < (1 << n); i++) {
        int sum = 0, count = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) > 0) {
                sum += nums[j];
                count++;
            }
        }
        if (sum == 0 || sum * n != totalSum * count) continue;
        if (count > 0 && count < n) return true;
    }
    return false;
}

