public boolean hasAllCodes(String s, int k) {
    Set<String> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        set.add(s.substring(i, i + k));
    }
    return set.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    int totalCombinations = 1 << k;
    boolean[] found = new boolean[totalCombinations];
    int count = 0;
    int value = 0;

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & (totalCombinations - 1);
        value |= s.charAt(i) - '0';

        if (i >= k - 1) {
            if (!found[value]) {
                found[value] = true;
                count++;
                if (count == totalCombinations) {
                    return true;
                }
            }
        }
    }

    return false;
}

