public int minInsertions(String s) {
        int leftBalance = 0;
        int rightBalance = 0;
        int insertions = 0;

        for (char c : s.toCharArray()) {
            if (c == '(') {
                if (rightBalance > 0) {
                    insertions++;
                    rightBalance--;
                }
                leftBalance++;
            } else {
                rightBalance++;
                if (leftBalance == 0) {
                    insertions++;
                } else {
                    leftBalance--;
                }
            }
        }

        insertions += leftBalance + 2 * rightBalance;

        return insertions;
    }

public int minInsertions(String s) {
    int balance = 0; // Tracks the balance of parentheses
    int insertions = 0; // Counts the number of insertions required
    int i = 0; // Index to traverse the string

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            balance++;
            i++;
        } else {
            // If the current character is ')', check the next character
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i += 2; // Skip the next character as it is a matching pair
            } else {
                insertions++; // Insert a matching ')' for the current ')'
                i++; // Move to the next character
            }
            balance--; // Decrease balance for unmatched ')'
            if (balance < 0) {
                // If balance becomes negative, insert a matching '(' before the current position
                balance = 0;
                insertions++;
            }
        }
    }
    // Add remaining insertions required to balance
    insertions += 2 * balance;
    return insertions;
}

public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int ans = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            if (close % 2 == 1) {
                ans++;
                close--;
            }
            open++;
        } else {
            close++;
            if (i + 1 == s.length() || s.charAt(i + 1) == '(') {
                ans++;
            } else {
                i++;
            }
        }
    }

    return ans + (open - close) + (close % 2);
}

public int minInsertions(String s) {
    int rightBalance = 0, leftBalance = 0, result = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftBalance++;
        } else {
            rightBalance++;
            if (rightBalance == 2) {
                if (leftBalance == 0) {
                    result++;
                } else {
                    leftBalance--;
                }
                rightBalance = 0;
            }
        }
    }

    result += leftBalance * 2 + (rightBalance == 1 ? 2 : 0);
    return result;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            balance--;
            if (balance == -1) {
                insertions++;
                balance = 0;
            }
        }
    }

    balance = Math.abs(balance);
    insertions += balance; // Each remaining '(' requires a corresponding ')'

    return insertions;
}

