public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int result = 0;

    for (int num : nums) {
        maxSum = Math.max(0, maxSum + num);
        minSum = Math.min(0, minSum - num);
        result = Math.max(result, Math.max(maxSum, -minSum));
    }

    return result;
}

