public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    while (b <= k) {
        fibs.add(b);
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (k >= fibs.get(i)) {
            count += k / fibs.get(i);
            k %= fibs.get(i);
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    fibNumbers.add(a);
    fibNumbers.add(b);
    while (b <= k) {
        int next = a + b;
        a = b;
        b = next;
        fibNumbers.add(b);
    }
    int count = 0;
    while (k > 0) {
        int maxIndex = fibNumbers.size() - 1;
        while (fibNumbers.get(maxIndex) > k) {
            maxIndex--;
        }
        k -= fibNumbers.get(maxIndex);
        count++;
    }
    return count;
}

public static int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    int nextFib = fibs.get(0) + fibs.get(1);
    while (nextFib <= k) {
        fibs.add(nextFib);
        nextFib = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
    }
    int count = 0;
    int index = fibs.size() - 1;
    while (k > 0) {
        if (k >= fibs.get(index)) {
            k -= fibs.get(index);
            count++;
        } else {
            index--;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Helper method to generate Fibonacci numbers up to k
    List<Integer> fibonacciNumbers = new ArrayList<>();
    int a = 1, b = 1;
    while (a <= k) {
        fibonacciNumbers.add(a);
        int next = a + b;
        a = b;
        b = next;
    }

    // Greedy approach to find the minimum number of Fibonacci numbers whose sum is k
    int count = 0;
    for (int i = fibonacciNumbers.size() - 1; i >= 0; i--) {
        while (k >= fibonacciNumbers.get(i)) {
            k -= fibonacciNumbers.get(i);
            count++;
        }
    }

    return count;
}

