public int maxUniqueSplit(String s) {
    return backtrack(s, new HashSet<>());
}

private int backtrack(String s, Set<String> set) {
    if (s.isEmpty()) {
        return set.size();
    }
    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (set.add(prefix)) {
            max = Math.max(max, backtrack(s.substring(i), set));
            set.remove(prefix);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    return helper(s, new HashSet<>());
}

private int helper(String s, Set<String> set) {
    if (s.isEmpty()) {
        return 0;
    }

    int max = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (set.add(prefix)) {
            max = Math.max(max, 1 + helper(s.substring(i), set));
            set.remove(prefix);
        }
    }
    return max;
}

public int maxUniqueSplit(String s) {
    Set<String> seen = new HashSet<>();
    return backtrack(s, seen, 0);
}

private int backtrack(String s, Set<String> seen, int start) {
    if (start == s.length()) {
        return seen.size();
    }

    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (!seen.contains(substring)) {
            seen.add(substring);
            maxUnique = Math.max(maxUnique, backtrack(s, seen, end));
            seen.remove(substring);
        }
    }

    return maxUnique;
}

