public static int singleNumber(int[] nums) {
    // Initialize counters for 1s and 2s
    int ones = 0, twos = 0;

    for (int num : nums) {
        // Update "twos" to include the current number if it was not already
        twos |= ones & num;

        // Update "ones" to include the current number
        ones ^= num;

        // Reset "ones" to ensure it doesn't have bits that appear three times
        int commonBits = ones & twos;
        ones &= ~commonBits;
        twos &= ~commonBits;
    }

    // The number that appears only once
    return ones;
}

