public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) return result;

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            if (i >= low && i <= high) {
                result.add(i);
            }
            if (i == 0 || i == 9) continue;
            queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            int lastDigit = num % 10;

            if (lastDigit > 0) {
                int nextNum = num * 10 + (lastDigit - 1);
                if (nextNum <= high) {
                    result.add(nextNum);
                    if (nextNum >= low) {
                        queue.offer(nextNum);
                    }
                }
            }

            if (lastDigit < 9) {
                int nextNum = num * 10 + (lastDigit + 1);
                if (nextNum <= high) {
                    result.add(nextNum);
                    if (nextNum >= low) {
                        queue.offer(nextNum);
                    }
                }
            }
        }

        Collections.sort(result);
        return result;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        Queue<Integer> queue = new LinkedList<>();
        List<Integer> result = new ArrayList<>();

        // Add all single-digit numbers to the queue
        for (int i = 0; i <= 9; i++) {
            queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();

            // If the current number is within the range, add it to the result
            if (current >= low && current <= high) {
                result.add(current);
            }

            // If the current number is greater than the high, break the loop
            if (current > high) {
                break;
            }

            // Get the last digit of the current number
            int lastDigit = current % 10;

            // Generate the next possible numbers
            if (lastDigit > 0) {
                queue.offer(current * 10 + lastDigit - 1);
            }
            if (lastDigit < 9) {
                queue.offer(current * 10 + lastDigit + 1);
            }
        }

        // Sort the result before returning
        return result.stream().sorted().collect(Collectors.toList());
    }

