public static int countDigitOne(int n) {
    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long divider = i * 10;
        long higher = n / divider;
        long current = (n / i) % 10;
        long lower = n % i;
        if (current == 0) {
            count += higher * i;
        } else if (current == 1) {
            count += higher * i + lower + 1;
        } else {
            count += (higher + 1) * i;
        }
    }
    return count;
}

