public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }

    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long high = n / (factor * 10);
        long cur = (n / factor) % 10;
        long low = n - (n / factor) * factor;

        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }
    }

    return count;
}

