                dp[i][j][1] = 1 + (i > 0 ? dp[i - 1][j][1] : 0); // vertical
                dp[i][j][2] = 1 + (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0); // diagonal
                dp[i][j][3] = 1 + (i > 0 && j < n - 1 ? dp[i - 1][j + 1][3] : 0); // anti-diagonal

