public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) {
        return 0;
    }

    int N = A.length;
    boolean[] visited = new boolean[N];
    return backtrack(A, visited, 0, new int[N]);
}

private static int backtrack(int[] A, boolean[] visited, int index, int[] current) {
    if (index == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(current[index - 1] + A[i])) {
            visited[i] = true;
            current[index] = A[i];
            count += backtrack(A, visited, index + 1, current);
            visited[i] = false;
        }
    }

    return count;
}

