public static int squarePermutations(int[] A) {
    int n = A.length;
    long total = 0;
    int[] count = new int[n];
    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i++) {
        dfs(A, i, 1, visited);
        count[A[i]]++;
    }
    for (int i = 0; i < n; i++) {
        if (visited[i]) continue;
        int sum = A[i] * A[i];
        int y = (int) Math.sqrt(sum);
        if (y * y != sum) continue;
        total += dfs(A, i, 1, visited, y);
    }
    for (int i = 1; i < n; i++) {
        total *= count[i];
    }
    return (int) total;
}

private static long dfs(int[] A, int i, int len, boolean[] visited) {
    if (len == A.length) return 1;
    visited[i] = true;
    long total = 0;
    for (int j = 0; j < A.length; j++) {
        if (visited[j] || A[i] + A[j] < 0) continue;
        int sum = A[i] + A[j];
        if (sum < 0) continue;
        int y = (int) Math.sqrt(sum);
        if (y * y == sum) {
            total += dfs(A, j, len + 1, visited);
        }
    }
    visited[i] = false;
    return total;
}

private static long dfs(int[] A, int i, int len, boolean[] visited, int prev) {
    if (len == A.length) return 1;
