    long total = 0;
    for (int j = 0; j < A.length; j++) {
        if (visited[j]) continue;
        int sum = prev + A[j];
        if (sum < 0) continue;
        int y = (int) Math.sqrt(sum);
        if (y * y == sum) {
            total += dfs(A, j, len + 1, visited, y);
        }
    }
    visited[i] = false;
    return total;
}

