        int count = 0;
        for (int i = index; i < A.length; i++) {
            if (isPerfectSquare(A[index] + prev)) {
                int temp = A[index];
                A[index] = A[i];
                A[i] = temp;
                count += countPermutations(A, index + 1, A[index]);
                temp = A[index];
                A[index] = A[i];
                A[i] = temp;
            }
        }
        return count;
    }

    // Entry point method
    public static int squarePermutations(int[] A) {
