public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;

    boolean[][] dp = new boolean[n][1 << n];
    dp[0][1 << 0] = true;

    for (int i = 1; i < n; i++) {
        for (int mask = 1; mask < (1 << n); mask++) {
            for (int j = 0; j < i; j++) {
                if (((mask >> j) & 1) != 0 && isPerfectSquare(A[j] + A[i])) {
                    dp[i][mask] = dp[i][mask] || dp[j][mask ^ (1 << i)];
                }
            }
        }
    }

    int result = 0;
    for (boolean row[]: dp[n-1])
        result += row ? 1 : 0;

    return result;
}

