public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Upward diagonal
            for (int i = Math.min(d, rows - 1); i >= 0 && d - i < cols; i--) {
                result[index++] = mat[i][d - i];
            }
        } else {
            // Downward diagonal
            for (int j = Math.min(d, cols - 1); j >= 0 && d - j < rows; j--) {
                result[index++] = mat[d - j][j];
            }
        }
    }

    return result;
}

