public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first digit that can be swapped to make the number greater
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, the number is already the greatest permutation
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of digits[i] that is greater than digits[i]
    int j;
    for (j = len - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the position i in ascending order
    Arrays.sort(digits, i + 1, len);

    // Convert the digits back to an integer
    return Integer.parseInt(new String(digits));
}

