            while (digits[j] <= digits[i]) {
                j--;
            }
            char temp = digits[i];
            digits[i] = digits[j];
            digits[j] = temp;

            Arrays.sort(digits, i + 1, length);

            return Integer.parseInt(new String(digits));
        }
    }

    return -1;
}

