public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        helper(n, n, new char[n], result);
        return result;
    }

private static void helper(int n, int m, char[] arr, List<String> result) {
        if (n == 0) {
            result.add(new String(arr));
            return;
        }
        if (n == 1) {
            result.add(new String(arr) + '0' + new StringBuilder(new String(arr)).reverse());
            result.add(new String(arr) + '1' + new StringBuilder(new String(arr)).reverse());
            result.add(new String(arr) + '8' + new StringBuilder(new String(arr)).reverse());
            return;
        }

        if (n != m) {
            arr[m - n] = '0';
        }

        arr[m + n - 1] = '0';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '1';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '6';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '8';
        helper(n - 2, m, arr, result);
        arr[m + n - 1] = '9';
        helper(n - 2, m, arr, result);
    }

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        helper(n, n, new char[n], result);
        return result;
    }

private static void helper(int n, int m, char[] arr, List<String> result) {
        if (n == 0) {
            result.add(new String(arr));
            return;
        }
        if (n == 1) {
            result.add(new String(arr));
            arr[m-1] = '0';
            result.add(new String(arr));
            return;
        }
        if (n < 1) return;

        char[] choices = {'0', '1', '6', '8', '9'};
        for (int i = 0; i < choices.length; i++) {
            if (n == m && choices[i] == '0') continue;
            arr[m+n-1] = choices[i];
            arr[m-n-1] = getComplement(choices[i]);
            helper(n-2, m, arr, result);
        }
    }

private static char getComplement(char c) {
        if (c == '6') return '9';
        if (c == '9') return '6';
        return c;
    }

public static List<String> centerSymmetricNumbers(int n) {
        // Helper method to recursively generate center symmetric numbers
        return helper(n, n);
    }

private static List<String> helper(int n, int m) {
        if (n == 0) return new ArrayList<>(List.of(""));
        if (n == 1) return new ArrayList<>(List.of("0", "1", "8"));

        List<String> list = helper(n - 2, m);
        List<String> res = new ArrayList<>();
        for (String s : list) {
            if (n != m) res.add("0" + s + "0");
            res.add("1" + s + "1");
            res.add("6" + s + "9");
            res.add("8" + s + "8");
            res.add("9" + s + "6");
        }
        return res;
    }

