            return new ArrayList<>(List.of("0", "1", "8"));
        }

        List<String> list = generateSymmetricNumbers(n - 2, m);
        List<String> result = new ArrayList<>();

        for (String s : list) {
            if (n != m) {
                result.add("0" + s + "0");
            }
            result.add("1" + s + "1");
            result.add("6" + s + "9");
            result.add("8" + s + "8");
            result.add("9" + s + "6");
        }

        return result;
    }

public static List<String> centerSymmetricNumbers(int n) {
        List<String> res = new ArrayList<>();
        if (n == 0) {
            return res;
        }
        if (n == 1) {
            res.add("0");
            res.add("1");
            res.add("8");
            return res;
        }

        helper(n, "", res);
        return res;
    }

private static void helper(int n, String s, List<String> res) {
        if (n == s.length()) {
            if (s.isEmpty() || s.charAt(0) != '0') {
                res.add(s);
            }
            return;
        }

        char[] map = {'0', '1', '6', '8', '9'};
        for (int i = 0; i < map.length; i++) {
            helper(n, s + map[i] + map[map.length - 1 - i], res);
        }
    }

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    // If the area is zero, the points are collinear and do not form a boomerang
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) != 0;
}

