public static int minPerfectSquareSum(int n) {
    if (n <= 3) return n;

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int x = 1; x * x <= i; x++) {
            dp[i] = Math.min(dp[i], dp[i - x * x] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Base cases
    if (n <= 3) {
        return n;
    }

    // This array will store the minimum number of perfect square numbers that sum up to i
    int[] dp = new int[n + 1];

    // All values in dp array are initialized to a large number (large enough to represent infinity)
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    // Base case initialization
    dp[0] = 0;

    // Fill dp array using bottom-up dynamic programming
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Create an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Base case: the minimum number of perfect squares for 0 is 0
    dp[0] = 0;

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the maximum possible (i)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // The result for n is stored in dp[n]
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Create an array to store the minimum number of squares for each value up to n
    int[] dp = new int[n + 1];

    // Base case: 0 can always be represented by 0 squares
    dp[0] = 0;

    // Precompute all squares that are less than or equal to n
    List<Integer> squares = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        squares.add(i * i);
    }
    Collections.sort(squares);

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int square : squares) {
            if (i - square >= 0) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            } else {
                break;
            }
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];

    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        reversedSentence.append(reversedWord);
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().trim();
}

